/* aesthetic toast v2.23.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-line: #e9e9e9;
  --ae-ok: #15714b;
  --ae-warn: #8a5f32;
  --ae-err: #a84138;
  --ae-line-dark: #262626;
  --ae-ok-dark: #6fd2a8;
  --ae-warn-dark: #c49d72;
  --ae-err-dark: #e58379;
  --ae-z-toast: 100;
  --ae-soft: 240ms;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-line: var(--ae-line-dark);
    --ae-ok: var(--ae-ok-dark);
    --ae-warn: var(--ae-warn-dark);
    --ae-err: var(--ae-err-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-line: var(--ae-line-dark);
  --ae-ok: var(--ae-ok-dark);
  --ae-warn: var(--ae-warn-dark);
  --ae-err: var(--ae-err-dark);
}

.ae-icon {
width: 1.2em;
  height: 1.2em;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  vertical-align: -0.2em;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) .ae-toast {
  background: var(--ae-wash);
      box-shadow: none;
  }
}

.ae-toasts {
position: fixed;
  right: 1.4em;
  bottom: 1.4em;
  z-index: var(--ae-z-toast);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.6em;
}

.ae-toast {
display: flex;
  align-items: baseline;
  gap: 0.6em;
  background: var(--ae-surface);
  border: 1px solid var(--ae-line);
  color: var(--ae-ink);
  font-size: 13px;
  line-height: 1.6;
  padding: 0.7em 1.1em;
  max-width: 26em;
  box-shadow:
    0 1px 2px rgba(0, 0, 0, 0.04),
    0 8px 28px rgba(0, 0, 0, 0.06);
  animation: ae-enter var(--ae-soft) var(--ae-ease) both;
}

.ae-toast.is-leaving {
opacity: 0;
  transition: opacity var(--ae-quick) var(--ae-ease);
}

.ae-toast-x {
background: transparent;
  border: 0;
  padding: 0;
  margin-left: 0.4em;
  min-width: 24px;
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  line-height: inherit;
  color: var(--ae-ink-faint);
  cursor: pointer;
  transition: color var(--ae-quick) var(--ae-ease);
}

.ae-toast-x:hover {
color: var(--ae-ink);
}

.dark .ae-toast,
[data-ae-mode='dark'] .ae-toast {
background: var(--ae-wash);
  box-shadow: none;
}

.ae-ok {
color: var(--ae-ok);
}

.ae-warn {
color: var(--ae-warn);
}

.ae-err {
color: var(--ae-err);
}

@keyframes ae-enter {
from {
    opacity: 0;
    transform: translateY(6px);
  }
}

/* the toast: news arrives at the edge and waits to be read.
   window.aeToast('Saved.', { status: 'ok' }) — ok|warn|err puts the
   hue on the glyph, the words stay ink. Toasts persist until
   dismissed or pushed out (the tray keeps four); pass { timeout: ms }
   to opt into self-dismissal — it is never the default. */
(() => {
  if (window.aeToast) return;
  const ICONS = {
    ok: '<path d="M20 6 9 17l-5-5"/>',
    warn: '<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"/><path d="M12 9v4"/><path d="M12 17h.01"/>',
    err: '<path d="M18 6 6 18"/><path d="m6 6 12 12"/>',
  };

  let tray = null;
  const ensureTray = () => {
    if (!tray) {
      tray = document.createElement('div');
      tray.className = 'ae-toasts';
      document.body.appendChild(tray);
    }
    return tray;
  };

  const dismiss = (toast) => {
    if (!toast.isConnected) return;
    toast.classList.add('is-leaving');
    setTimeout(() => toast.remove(), 200);
  };

  window.aeToast = (message, opts) => {
    const { status, timeout } = opts || {};
    const toast = document.createElement('div');
    toast.className = 'ae-toast';
    toast.setAttribute('role', 'status');
    if (status && ICONS[status]) {
      const i = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      i.setAttribute('class', `ae-icon ae-${status}`);
      i.setAttribute('viewBox', '0 0 24 24');
      i.innerHTML = ICONS[status];
      toast.appendChild(i);
    }
    toast.appendChild(document.createTextNode(message));
    const x = document.createElement('button');
    x.className = 'ae-toast-x';
    x.setAttribute('aria-label', 'dismiss');
    x.textContent = '✕';
    x.addEventListener('click', () => dismiss(toast));
    toast.appendChild(x);

    const t = ensureTray();
    t.appendChild(toast);
    while (t.children.length > 4) t.firstElementChild.remove();
    if (timeout) setTimeout(() => dismiss(toast), timeout);
    return toast;
  };
})();
